import re, io, sys
def norm(s):
    s = s.replace('ﬁ','fi').replace('ﬂ','fl')
    s = re.sub(r'-\n', '', s)          # PDF hyphenation
    s = re.sub(r'\s+', ' ', s)
    return s
def nospace(s):
    return re.sub(r'\s+', '', s)
