tot=0; miss=0
for key, path in files.items():
    raw = io.open(path, encoding='utf-8', errors='replace').read()
    if key == 'weberwulff':
        t = nospace(raw); qs = ww_quotes
        for q in qs:
            tot+=1; ok = nospace(q) in t
            if not ok: miss+=1
            print(f"[{key}] {'OK ' if ok else 'MISS'} :: {q}")
        continue
    t = norm(raw)
    t2 = t.replace('- ', '')
    for q in quotes[key]:
        tot+=1
        qn = re.sub(r'\s+',' ', q)
        ok = (qn in t) or (qn in t2) or (qn.replace('’',"'") in t.replace('’',"'"))
        if not ok: miss+=1
        print(f"[{key}] {'OK ' if ok else 'MISS'} :: {q}")
print(f"TOTAL {tot} checked, {miss} missing")
